import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; A=data[1:]
    M=max(A)
    phi=list(range(M+1))
    for i in range(2,M+1):
        if phi[i]==i:
            for j in range(i,M+1,i): phi[j]-=phi[j]//i
    spf=list(range(M+1))
    if M>=1: spf[1]=1
    for i in range(2,int(M**0.5)+1):
        if spf[i]==i:
            for j in range(i*i,M+1,i):
                if spf[j]==j: spf[j]=i
    cache={}
    def divisors(x):
        z=x; fac=[]
        while z>1:
            p=spf[z]; e=0
            while z%p==0: z//=p; e+=1
            fac.append((p,e))
        ds=[1]
        for p,e in fac:
            old=ds[:]; mul=1
            for _ in range(e):
                mul*=p
                ds += [v*mul for v in old]
        return ds
    F=[0]*(M+1); ans=0; pw=1; out=[]
    for a in A:
        ds=cache.get(a)
        if ds is None: ds=cache.setdefault(a,divisors(a))
        s=0
        for d in ds: s += phi[d]*F[d]
        ans=(2*ans+s)%MOD
        out.append(str(ans))
        for d in ds: F[d]=(F[d]+pw)%MOD
        pw=pw*2%MOD
    print('\n'.join(out))
main()

