class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        L = len(s)
        fac = [1] * (L + 1)
        for i in range(1, L + 1):
            fac[i] = fac[i - 1] * i % MOD
        invfac = [1] * (L + 1)
        invfac[L] = pow(fac[L], MOD - 2, MOD)
        for i in range(L, 0, -1):
            invfac[i - 1] = invfac[i] * i % MOD

        def choose(n, r):
            if r < 0 or r > n:
                return 0
            return fac[n] * invfac[r] % MOD * invfac[n - r] % MOD

        good = [False] * (L + 1)
        for ones in range(1, L + 1):
            value = ones
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[ones] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = L - i - 1
                for total_ones in range(prefix_ones, L + 1):
                    if good[total_ones]:
                        answer = (answer + choose(remaining, total_ones - prefix_ones)) % MOD
                prefix_ones += 1
        return answer

