    n=next(it); m=next(it); q=next(it)
    seg=[]
    for k in range(m):
        s=next(it); t=next(it)
        if s<t: seg.append((s,t,1))
        else: seg.append((t,s,-1))
    # Conservative exact pairwise obstruction detection; process all pairs by sweep with active interval heaps.
    bad=[0]*m
    # crossing same-oriented intervals: direct quadratic avoided via ordered sweep and segment tree on right endpoints
    for typ in (1,-1):
        arr=[(l,r,i) for i,(l,r,d) in enumerate(seg) if d==typ]
        arr.sort(key=lambda x:x[0])
        # prior intervals grouped by right endpoint; retain largest index, Fenwick range maximum
        rs=sorted(set(r for l,r,i in arr)); z=len(rs); bit=[0]*(z+2)
        def upd(x,v):
            x+=1
            while x<=z:
                if v>bit[x]: bit[x]=v
                x+=x&-x
        def pref(x):
            x+=1; v=0
            while x:
                v=max(v,bit[x]); x-=x&-x
            return v
        # Fenwick gives prefix, use reversed for suffix/range; query all prior with l<lcur and r in (lcur,rcur)
        # use simple active list for correctness (fallback)
        prior=[]
        for l,r,j in arr:
            best=0
            for x,y,i in prior:
                if x<l<y<r and i+1>best: best=i+1
            if best: bad[j]=max(bad[j],best)
            prior.append((l,r,j))
    # shared-endpoint opposite directions
    groups={}
    for i,(l,r,d) in enumerate(seg):
        for e,side in ((l,0),(r,1)):
            key=(e,side,d)
            groups.setdefault(key,[]).append((l,r,i))
    for e in (set(x[0] for x in seg)|set(x[1] for x in seg)):
        for side in (0,1):
            p=groups.get((e,side,1),[]); z=groups.get((e,side,-1),[])
            for _,_,i in p:
                for _,_,j in z:
                    if i<j: bad[j]=max(bad[j],i+1)
                    elif j<i: bad[i]=max(bad[i],j+1)
