    for i in range(m):
        mx=max(mx,bad[i])
        # mx is largest left endpoint among conflicts ending no later than i
        out.append(mx)
    for _ in range(q):
        l=next(it); r=next(it)
        outv='Yes' if out[r-1]<l else 'No'
        print(outv)
