import sys, heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    graph = [row.decode() for row in data[1:]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    out_mask = [[0] * 26 for _ in range(n)]

    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                k = ord(ch) - 97
                incoming[v][k].append(u)
                outgoing[u][k].append(v)
                out_mask[u][k] |= 1 << v

    all_vertices = (1 << n) - 1
    missing_mask = [
        [all_vertices ^ out_mask[u][k] for k in range(26)]
        for u in range(n)
    ]

    inf = 10**9
    dist = [inf] * (n * n)
    heap = []
    for i in range(n):
        dist[i * n + i] = 0
        heapq.heappush(heap, (0, i, i))

    for u in range(n):
        for k in range(26):
            for v in outgoing[u][k]:
                if u != v:
                    dist[u * n + v] = 1
                    heapq.heappush(heap, (1, u, v))

    while heap:
        cur, x, y = heapq.heappop(heap)
        if dist[x * n + y] != cur:
            continue
        candidate = cur + 2
        for k in range(26):
            right_mask = out_mask[y][k]
            if not right_mask:
                continue
            for u in incoming[x][k]:
                bits = right_mask & missing_mask[u][k]
                while bits:
                    bit = bits & -bits
                    v = bit.bit_length() - 1
                    bits -= bit
                    pos = u * n + v
                    if dist[pos] > candidate:
                        dist[pos] = candidate
                        heapq.heappush(heap, (candidate, u, v))

    for i in range(n):
        print(*(-1 if dist[i * n + j] == inf else dist[i * n + j]
                for j in range(n)))

if __name__ == '__main__':
    main()

