def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    U = [0] * n
    D = [0] * n
    p = 2
    for i in range(n):
        U[i], D[i] = data[p], data[p + 1]
        p += 2

    def feasible(h):
        lo = max(0, h - D[0])
        hi = min(U[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            new_lo = max(0, h - D[i], lo - x)
            new_hi = min(U[i], h, hi + x)
            if new_lo > new_hi:
                return False
            lo, hi = new_lo, new_hi
        return True

    low = 0
    high = min(u + d for u, d in zip(U, D)) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(sum(U) + sum(D) - n * low)

