import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    r = 0
    for c in range(n):
        q = None
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                q = i
                break
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        x = 1 << free
        for i, pivot in enumerate(pivots):
            if (rows[i] >> free) & 1:
                x |= 1 << pivot
        basis.append(x)

    values = [0] * n
    for bit, vector in enumerate(basis):
        for vertex in range(n):
            if (vector >> vertex) & 1:
                values[vertex] |= 1 << bit

    if any(x == 0 for x in values):
