from bisect import bisect_left, bisect_right

def main():
    data=sys.stdin.buffer.read().split(); it=iter(data)
    n=int(next(it)); q=int(next(it)); s=next(it).decode()
    p1=[0]*(n+1); p2=[0]*(n+1); sl=[]
    for i,c in enumerate(s):
        p1[i+1]=p1[i]+(c=='1'); p2[i+1]=p2[i]+(c=='2')
        if c=='/': sl.append(i)
    out=[]
    for _ in range(q):
        L=int(next(it))-1; R=int(next(it))-1
