class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)
        odd, even = (n + 1) // 2, n // 2
        used = [False] * (n + 1)
        ans = []
        def completions(ro, re, nxt, length):
            if length == 0:
                return int(ro == 0 and re == 0)
            need_o = (length + 1) // 2 if nxt == 1 else length // 2
            need_e = length - need_o
            if (ro, re) != (need_o, need_e):
                return 0
            return min(CAP, fact[ro] * fact[re])
        prev = None
        for pos in range(n):
            for x in range(1, n + 1):
                parity = x & 1
                if used[x] or (prev is not None and parity == prev):
                    continue
                no, ne = odd - parity, even - (1 - parity)
                cnt = completions(no, ne, 1 - parity, n - pos - 1)
                if k > cnt:
                    k -= cnt
                else:
                    used[x] = True
                    odd, even, prev = no, ne, parity
                    ans.append(x)
                    break
            else:
                return []
        return ans

