    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p = [1] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        coeff = []
        for j in range(m):
            if n - 1 - j == j:
                coeff.append(p[j])
            else:
                coeff.append((p[j] + p[n - 1 - j]) % k)

        # suf[j] is a bitset of remainders obtainable by positions j..m-1.
        suf = [0] * (m + 1)
        suf[m] = 1
        for j in range(m - 1, -1, -1):
            c = coeff[j]
            mask = 0
            for r in range(k):
                if (suf[j + 1] >> r) & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * c) % k)
            suf[j] = mask

        ans = []
        rem = 0
        for j, c in enumerate(coeff):
            lower = 1 if j == 0 else 0
            for d in range(9, lower - 1, -1):
                new_rem = (rem + d * c) % k
                if (suf[j + 1] >> ((-new_rem) % k)) & 1:
                    ans.append(str(d))
                    rem = new_rem
                    break

        left = ''.join(ans)
        return left + (left[-2::-1] if n % 2 else left[::-1])

