from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        weight = [0] * (n + 1)
        for i in range(n):
            q = nxt[i]
            weight[i] = nums[i] * (q - i) - (pref[q] - pref[i])

        levels = n.bit_length()
        up = [nxt]
        sums = [weight[:n]]
        for _ in range(1, levels):
            prev_up, prev_sum = up[-1], sums[-1]
            cur_up = [0] * n
            cur_sum = [0] * n
            for i in range(n):
                q = prev_up[i]
                cur_up[i] = n if q == n else prev_up[q]
                cur_sum[i] = prev_sum[i] + (0 if q == n else prev_sum[q])
            up.append(cur_up)
            sums.append(cur_sum)

        def cost(left, right):
            cur = left
            total = 0
            for j in range(levels - 1, -1, -1):
                q = up[j][cur]
                if q <= right:
                    total += sums[j][cur]
                    cur = q
            return total + nums[cur] * (right - cur + 1) - (pref[right + 1] - pref[cur])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

