from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    fs = []
    pos = 2
    for _ in range(n):
        a, b = data[pos], data[pos + 1]
        pos += 2
        fs.append((a, b, a - 1))

    def cmp(x, y):
        ax, bx, dx = x
        ay, by, dy = y
        if dx == 0:
            return 0 if dy == 0 else -1
        if dy == 0:
            return 1
        cross = bx * dy - by * dx
        return -1 if cross > 0 else (1 if cross < 0 else 0)

    fs.sort(key=cmp_to_key(cmp))
    dp = [None] * (k + 1)
