class Solution:
    def makeStringGood(self, s: str) -> int:
        a = [0] * 26
        for c in s:
            a[ord(c) - 97] += 1
        n = len(s)
        INF = 10**9
        answer = n
        for k in set(a):
            if k == 0:
                continue
            dp = [INF] * (n + 1)
            dp[0] = 0
            for cnt in a:
                pref = [INF] * (n + 1)
                suff = [INF] * (n + 1)
                best = INF
                for p, v in enumerate(dp):
                    best = min(best, v - p)
                    pref[p] = best
                best = INF
                for p in range(n, -1, -1):
                    best = min(best, dp[p] + p)
                    suff[p] = best
                ndp = [INF] * (n + 1)
                for target in (0, k):
                    b = cnt - target
                    for flow in range(n + 1):
                        boundary = flow - b
                        value = INF
                        if boundary >= 0:
                            value = pref[min(n, boundary)] - b + 2 * flow
                        if boundary <= n:
                            value = min(value, suff[max(0, boundary)] + b)
                        if value < ndp[flow]:
                            ndp[flow] = value
                dp = ndp
            answer = min(answer, dp[0])
        return answer

