import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, L = data[:3]
    rest = data[3:]
    values = rest[:N] + rest[N:N + M] + rest[N + M:N + M + L]
    K = N + M + L
    power = [3 ** i for i in range(K)]
    initial = sum(power[:N]) + sum(2 * power[i] for i in range(N, N + M))

    @lru_cache(None)
    def winning(state, player):
        digit = [0] * K
        x = state
        for i in range(K):
            digit[i] = x % 3
            x //= 3
        for i in range(K):
            if digit[i] != player:
                continue
            table_state = state - digit[i] * power[i]
            for j in range(K):
                if digit[j] == 0 and values[j] < values[i]:
                    next_state = table_state + player * power[j]
                    if not winning(next_state, 3 - player):
                        return True
            if not winning(table_state, 3 - player):
                return True
        return False

    print("Takahashi" if winning(initial, 1) else "Aoki")

if __name__ == "__main__":
    main()

