    freq=[0]*n
    for s in data[2:2+H]:
        freq[int(s,2)]+=1
    cost=[min(k.bit_count(), W-k.bit_count()) for k in range(n)]
    fwht(freq)
    fwht(cost)
    for i in range(n):
        freq[i] *= cost[i]
    fwht(freq)
    print(min(v//n for v in freq))

