class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return []
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        starts_a = occurrences(A)
        starts_b = occurrences(B)
        starts_c = occurrences(C)
        import bisect
        la, lb, lc = len(A), len(B), len(C)
        answer = n + 1
        starts = range(n + 1) if not A else starts_a
        for start in starts:
            after_a = start + la
            if B:
                k = bisect.bisect_left(starts_b, after_a)
                if k == len(starts_b):
                    continue
                start_b = starts_b[k]
            else:
                start_b = after_a
            after_b = start_b + lb
            if C:
                k = bisect.bisect_left(starts_c, after_b)
                if k == len(starts_c):
                    continue
                start_c = starts_c[k]
            else:
                start_c = after_b
            answer = min(answer, start_c + lc - start)
        return -1 if answer == n + 1 else answer

