def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [None] * n
    answer = [0] * n

    for start in range(n):
        if potential[start] is not None:
            continue
        potential[start] = 0
        stack = [start]
        vertices = []
        while stack:
            v = stack.pop()
            vertices.append(v)
            for w, z in graph[v]:
                value = potential[v] ^ z
                if potential[w] is None:
                    potential[w] = value
                    stack.append(w)
                elif potential[w] != value:
                    print(-1)
                    return

        ones = [0] * 30
        for v in vertices:
            value = potential[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1

        shift = 0
        size = len(vertices)
        for bit in range(30):
            if 2 * ones[bit] > size:
                shift |= 1 << bit
        for v in vertices:
            answer[v] = shift ^ potential[v]

    print(*answer)

