class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        start = [0] * n
        end = [0] * n
        postorder = []
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                start[v] = len(postorder)
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                postorder.append(v)
                end[v] = len(postorder) - 1

        text = ''.join(s[v] for v in postorder)
        transformed = '^#' + '#'.join(text) + '#$'
        radius = [0] * len(transformed)
        center = right = 0
        for i in range(1, len(transformed) - 1):
            mirror = 2 * center - i
            if i < right:
                radius[i] = min(right - i, radius[mirror])
            while transformed[i + 1 + radius[i]] == transformed[i - 1 - radius[i]]:
                radius[i] += 1
            if i + radius[i] > right:
                center, right = i, i + radius[i]

        answer = []
        for v in range(n):
            left, right_end = start[v], end[v]
            center_pos = left + right_end + 2
            answer.append(radius[center_pos] >= right_end - left + 1)
        return answer

