class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0
        lines = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, p, left, right):
            current = lines[p]
            if current is None:
                lines[p] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                lines[p], line = line, current
            if left == right:
                return
            if value(line, left) > value(lines[p], left):
                add(line, p * 2, left, mid)
            elif value(line, right) > value(lines[p], right):
                add(line, p * 2 + 1, mid + 1, right)

        def query(x, p, left, right):
            best = value(lines[p], x) if lines[p] is not None else -10**30
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                return max(best, query(x, p * 2, left, mid))
            return max(best, query(x, p * 2 + 1, mid + 1, right))

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            answer = query(j, 1, 0, n - 1)
            add((nums[j], answer - j * nums[j]), 1, 0, n - 1)
        return answer

