class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq
        L = len(str(n))
        N = 10 ** L
        prime = bytearray(b'\x01') * N
        prime[0] = 0
        prime[1] = 0
        for i in range(2, int(N ** 0.5) + 1):
            if prime[i]:
                prime[i*i:N:i] = b'\x00' * (((N - 1 - i*i) // i) + 1)
        if prime[n] or prime[m]:
            return -1
        inf = 10 ** 18
        dist = [inf] * N
        dist[n] = n
        pq = [(n, n)]
        places = [10 ** i for i in range(L)]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in places:
                digit = (x // p) % 10
                if digit < 9:
                    y = x + p
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))
                if digit > 0:
                    y = x - p
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))
        return -1

