class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z0 = [0] * n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z0[i] = min(r - i, z0[i-l])
            while i + z0[i] < n and nums[z0[i]] == nums[i+z0[i]]:
                z0[i] += 1
            if i + z0[i] > r:
                l, r = i, i + z0[i]
        ans = 0
        for i in range(1, n-1):
            first_ok = z0[i] >= i
            if first_ok and 2*i < n:
                ans += n - 2*i
            m = min((n-i)//2, i-1) if first_ok else (n-i)//2
            if m <= 0:
                continue
            z = [0] * (n-i)
            l = r = 0
            for k in range(1, n-i):
                if k < r:
                    z[k] = min(r-k, z[k-l])
                while k + z[k] < n-i and nums[i+z[k]] == nums[i+k+z[k]]:
                    z[k] += 1
                if k + z[k] > r:
                    l, r = k, k+z[k]
            for d in range(1, m+1):
                if z[d] >= d:
                    ans += 1
        return ans

