class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def atmost(K):
            if K < 0:
                return 0
            left = 0
            cons = 0
            last = [-1] * 5
            mp = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
            ans = 0
            for r, ch in enumerate(word):
                if ch in mp:
                    last[mp[ch]] = r
                else:
                    cons += 1
                while cons > K:
                    if word[left] not in mp:
                        cons -= 1
                    left += 1
                first = min(last)
                if first >= left:
                    ans += first - left + 1
            return ans
        return atmost(k) - atmost(k - 1)

